cypress_script:
describe('Buttons Interaction Tests', () => {
  it('should click the Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#sp5Bi').click();
    cy.url().should('include', '/buttons');
  });

  it('should not navigate when right-clicking the Right Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#rightClickBtn').rightclick();
    cy.url().should('include', '/buttons');
    cy.get('button#rightClickBtn').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Buttons Interaction Tests', () => {
  test('should click the Click Me button', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.click('button#sp5Bi');
    expect(page.url()).toContain('/buttons');
  });

  test('should not navigate when right-clicking the Right Click Me button', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.click('button#rightClickBtn', { button: 'right' });
    expect(page.url()).toContain('/buttons');
    const buttonVisible = await page.isVisible('button#rightClickBtn');
    expect(buttonVisible).toBe(true);
  });
});
